 76	/**
 77	 * @brief Khởi tạo ngoại vi phần cứng: 4 LED và nút WAKEUP PA0.
 78	 */
 79	static void prvSetupHardware(void)
 80	{
 81	    /* Bật clock AHB1 cho GPIOA, GPIOD, GPIOG, GPIOK */
 82	    RCC->AHB1ENR |= RCC_AHB1ENR_GPIOAEN | RCC_AHB1ENR_GPIODEN | RCC_AHB1ENR_GPIOGEN | RCC_AHB1ENR_GPIOKEN;
 83	
 84	    /* Cấu hình PA0 (Nút WAKEUP): Chế độ Input (00), Pull-down (10) */
 85	    GPIOA->MODER &= ~(3UL << (BUTTON_PIN * 2));
 86	    GPIOA->PUPDR &= ~(3UL << (BUTTON_PIN * 2));
 87	    GPIOA->PUPDR |= (2UL << (BUTTON_PIN * 2));
 88	
 89	    /* Cấu hình PG6 (LED1): Chế độ Output (01), tắt ban đầu (LED tích cực mức thấp) */
 90	    GPIOG->MODER &= ~(3UL << (LED1_PIN * 2));
 91	    GPIOG->MODER |= (1UL << (LED1_PIN * 2));
 92	    GPIOG->BSRR = (1UL << LED1_PIN);
 93	
 94	    /* Cấu hình PD4 (LED2) & PD5 (LED3): Chế độ Output (01), tắt ban đầu */
 95	    GPIOD->MODER &= ~((3UL << (LED2_PIN * 2)) | (3UL << (LED3_PIN * 2)));
 96	    GPIOD->MODER |= ((1UL << (LED2_PIN * 2)) | (1UL << (LED3_PIN * 2)));
 97	    GPIOD->BSRR = (1UL << LED2_PIN) | (1UL << LED3_PIN);
 98	
 99	    /* Cấu hình PK3 (LED4): Chế độ Output (01), tắt ban đầu */
100	    GPIOK->MODER &= ~(3UL << (LED4_PIN * 2));
101	    GPIOK->MODER |= (1UL << (LED4_PIN * 2));
102	    GPIOK->BSRR = (1UL << LED4_PIN);
103	}
104	
105	/**
106	 * @brief Task 1: Nháy LED1 (PG6) theo chu kỳ.
107	 */
108	static void vTaskLED1(void *arg)
109	{
110	    (void)arg;
111	    for (;;) {
112	        GPIOG->BSRR = (1UL << (LED1_PIN + 16)); /* Bật LED1 (mức thấp) */
113	        rtos_delay_ms(500U);
114	        GPIOG->BSRR = (1UL << LED1_PIN);        /* Tắt LED1 (mức cao) */
115	        rtos_delay_ms(500U);
116	    }
117	}
118	
119	/**
120	 * @brief Task 2: Nháy LED2 (PD4) theo chu kỳ.

121	 */
122	static void vTaskLED2(void *arg)
123	{
124	    (void)arg;
125	    for (;;) {
126	        GPIOD->BSRR = (1UL << (LED2_PIN + 16)); /* Bật LED2 */
127	        rtos_delay_ms(200U);
128	        GPIOD->BSRR = (1UL << LED2_PIN);        /* Tắt LED2 */
129	        rtos_delay_ms(200U);
130	    }
131	}
132	
133	/**
134	 * @brief Task 3: Đọc nút bấm PA0 (quét định kỳ, chống rung) và gửi thông điệp vào Queues.
135	 */
136	static void vTaskButton(void *arg)
137	{
138	    (void)arg;
139	    uint8_t prev_state = 0;
140	
141	    for (;;) {
142	        uint8_t state = (GPIOA->IDR & (1UL << BUTTON_PIN)) ? 1U : 0U;
143	        if (state && !prev_state) {
144	            uint32_t msg = 1U;
145	            rtos_queue_send(&xButtonQueue, &msg, 0U);
146	            rtos_queue_send(&xUIQueue, &msg, 0U);
147	        }
148	        prev_state = state;
149	        rtos_delay_ms(30U);
150	    }
151	}
152	
153	/**
154	 * @brief Task 4: Chờ tín hiệu từ Queue để đảo trạng thái LED3 (PD5).
155	 */
156	static void vTaskLED3(void *arg)
157	{
158	    (void)arg;
159	    uint32_t rx_msg = 0;
160	    uint8_t led_state = 0;
161	
162	    for (;;) {
163	        if (rtos_queue_receive(&xButtonQueue, &rx_msg, 1000U) == RTOS_OK) {
164	            led_state = !led_state;
165	            if (led_state) {
166	                GPIOD->BSRR = (1UL << (LED3_PIN + 16)); /* Bật LED3 */
167	            } else {
168	                GPIOD->BSRR = (1UL << LED3_PIN);        /* Tắt LED3 */
169	            }
170	        }
171	    }
172	}
173	
174	/**
175	 * @brief Task 5: Giám sát hệ thống qua LED4 (PK3) - nhịp tim định kỳ.
176	 */
177	static void vTaskMonitor(void *arg)
178	{
179	    (void)arg;
180	    for (;;) {
181	        GPIOK->BSRR = (1UL << (LED4_PIN + 16)); /* Bật LED4 */
182	        rtos_delay_ms(100U);
183	        GPIOK->BSRR = (1UL << LED4_PIN);        /* Tắt LED4 */
184	        rtos_delay_ms(1900U);
185	    }
186	}
187	
188	/**
189	 * @brief Task 6: Quản lý hiển thị LCD DSI OTM8009A và quét cảm ứng điện dung FT6206.
190	 */
191	static void vTaskLCD(void *arg)
192	{
193	    (void)arg;
194	    uint32_t rx_msg = 0;
195	
196	    /* Khởi tạo SDRAM và màn hình LCD DSI */
197	    UI_Init();
198	
199	    /* Khởi tạo cảm ứng điện dung qua I2C */
200	    Touch_Init();
201	
202	    uint8_t touch_was_pressed = 0;
203	
204	    for (;;) {
205	        /* Chờ tín hiệu từ nút bấm vật lý PA0 (timeout để kết hợp quét cảm ứng) */
206	        if (rtos_queue_receive(&xUIQueue, &rx_msg, 40U) == RTOS_OK) {
207	            UI_ToggleScreen();
208	        }
209	
210	        /* Quét điểm chạm trên màn hình cảm ứng */
211	        uint16_t tx = 0;
212	        uint16_t ty = 0;
213	        if (Touch_Read(&tx, &ty)) {
214	            if (!touch_was_pressed) {
215	                UI_HandleTouch(tx, ty);
216	                touch_was_pressed = 1U;
217	            }
218	        } else {
219	            touch_was_pressed = 0U;
220	        }
221	    }
222	}
223	
224	/**
225	 * @brief Điểm khởi nhập chính của ứng dụng firmware.
226	 */
227	int main(void)
228	{
229	    /* 1. Thiết lập phần cứng (GPIO LED và nút bấm) */
230	    prvSetupHardware();
231	
232	    /* 2. Khởi tạo lõi RTOS */
233	    rtos_init();
234	
235	    /* 3. Khởi tạo hàng đợi tĩnh IPC cho sự kiện nút bấm */
236	    rtos_queue_init(
237	        &xButtonQueue,
238	        button_queue_storage,
239	        sizeof(uint32_t),
240	        QUEUE_CAPACITY
241	    );
242	
243	    rtos_queue_init(
244	        &xUIQueue,
245	        ui_queue_storage,
246	        sizeof(uint32_t),
247	        QUEUE_CAPACITY
248	    );
249	
250	    /* 4. Tạo 6 tác vụ với các mức ưu tiên riêng biệt (0 cao nhất, 31 idle).
251	     * Nhân O(1) quy định mỗi mức ưu tiên chỉ gắn với 1 tác vụ:
252	     * - Button (1U): ưu tiên cao nhất để quét nút bấm kịp thời
253	     * - LCD (2U): ưu tiên cao cho tương tác giao diện và cảm ứng
254	     * - LED3 (3U): phản hồi sự kiện từ hàng đợi nút bấm
255	     * - LED2 (4U): tác vụ nháy chu kỳ 400 ms
256	     * - LED1 (5U): tác vụ nháy chu kỳ 1000 ms
257	     * - Monitor (6U): tác vụ giám sát nhịp tim hệ thống
258	     */
259	    rtos_task_create(&tcb_button,  "BtnPoll",     vTaskButton,  NULL, 1U, stack_button,  RTOS_DEFAULT_STACK_WORDS);
260	    rtos_task_create(&tcb_lcd,     "LCD_Task",    vTaskLCD,     NULL, 2U, stack_lcd,     1024U);
261	    rtos_task_create(&tcb_led3,    "LED3_Queue",  vTaskLED3,    NULL, 3U, stack_led3,    RTOS_DEFAULT_STACK_WORDS);
262	    rtos_task_create(&tcb_led2,    "LED2_400ms",  vTaskLED2,    NULL, 4U, stack_led2,    RTOS_DEFAULT_STACK_WORDS);
263	    rtos_task_create(&tcb_led1,    "LED1_1000ms", vTaskLED1,    NULL, 5U, stack_led1,    RTOS_DEFAULT_STACK_WORDS);
264	    rtos_task_create(&tcb_monitor, "Monitor",     vTaskMonitor, NULL, 6U, stack_monitor, RTOS_DEFAULT_STACK_WORDS);
265	
266	    /* 5. Khởi động bộ lập lịch RTOS tiền định */
267	    rtos_start();
268	
269	    /* Bẫy vòng lặp nếu nhân bị dừng bất thường */
270	    while (1) {
271	        __WFI();
272	    }
273	
274	    return 0;
275	}

