48	/**
49	 * @brief Ve nut bam co vien ro net va chu can chinh giua dung hop nut
50	 */
51	static void UI_DrawButton(uint16_t x, uint16_t y, uint16_t w, uint16_t h,
52	                          uint32_t bg_color, uint32_t border_color, uint32_t text_color,
53	                          sFONT *font, const char *label)
54	{
55	    /* 1. Nen nut */
56	    BSP_LCD_SetTextColor(bg_color);
57	    BSP_LCD_FillRect(x, y, w, h);
58	
59	    /* 2. Khung vien nut ro net */
60	    BSP_LCD_SetTextColor(border_color);
61	    BSP_LCD_DrawRect(x, y, w, h);
62	    BSP_LCD_DrawRect(x + 1, y + 1, w - 2, h - 2);
63	
64	    /* 3. Can chu o chinh giua hop nut */
65	    uint32_t len = 0;
66	    while (label[len] != '\0') {
67	        len++;
68	    }
69	    uint16_t text_width = len * font->Width;
70	    uint16_t text_x = x + ((w > text_width) ? ((w - text_width) / 2) : 0);
71	    uint16_t text_y = y + ((h > font->Height) ? ((h - font->Height) / 2) : 0);
72	
73	    BSP_LCD_SetBackColor(bg_color);
74	    BSP_LCD_SetTextColor(text_color);
75	    BSP_LCD_SetFont(font);
76	    BSP_LCD_DisplayStringAt(text_x, text_y, (uint8_t *)label, LEFT_MODE);
77	}
